steps.script:
var d = AIPlayer.request_suggestion()
var rec = {}
for r in d.get("_ai_decision_records", []):
	if str(r.get("decision_type", "")) == "secondary_discard":
		rec = r
Engine.set_meta("fc_desc", str(d.get("_ai_description", "")))
return "%s|%s|%s" % [d.get("type", ""), str(d.get("_ai_description", "")).begins_with("Discard 'Bring it Down' for +1 CP (forecast"), str(rec.get("context", {}).get("forecast", false))]

var p = int(Engine.get_meta("fc_player"))
var cp0 = int(GameState.state["players"][str(p)]["cp"])
var d = AIPlayer.request_suggestion()
var r = PhaseManager.get_current_phase_instance().execute_action(d)
var ids = SecondaryMissionManager.get_active_missions(p).map(func(m): return m["id"])
return "%s|%s|%d" % [str(r.get("success", false)), str(ids), int(GameState.state["players"][str(p)]["cp"]) - cp0]
